class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        # 记录已经遍历过的数字及其索引：{num: index}
        # 作用：O(1) 时间复杂度查找 target - num 是否存在
        num_map = {}

        for i, num in enumerate(nums):
            # 计算当前数字所需要的配对数字
            complement = target - num

            # 检查配对数字是否在之前已经出现过
            # 这个分支是这个套路的核心，体现了『边遍历边查表』的模式
            if complement in num_map:
                # 如果存在，直接返回答案（配对数字的索引，当前数字的索引）
                return [num_map[complement], i]

            # 尚未找到配对数字，将当前数字及其索引记录到哈希表中
            # 注意：只有在未找到时才加入，避免用自身匹配自己（如 target=6, num=3 的情况）
            num_map[num] = i

        return []

class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        # 外层循环选定第一个数字
        for i in range(len(nums)):
            # 内层循环只看 i 后面的数字，避免重复且保证不使用同一个元素两次
            for j in range(i + 1, len(nums)):
                # 检查组合是否满足条件
                if nums[i] + nums[j] == target:
                    return [i, j]
        return []

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # 1. 确保 nums1 是较短的数组，将二分查找范围限制在较短数组上，减小时间复杂度
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        # 2. 定位二分的边界，针对 nums1 的分隔线位置 [0, m] 进行二分
        left, right = 0, m
        # 中位数理论划分使得左半部分有 (m + n + 1) // 2 个元素（奇数时左半边多1个）
        half_len = (m + n + 1) // 2

        while left <= right:
            # 3. i 为 nums1 的分割线，j 为 nums2 的分割线
            i = (left + right) // 2
            j = half_len - i

            # 4. 判断分割线是否合理，结合边界处理无穷大/小的情况
            nums1_left_max = float('-inf') if i == 0 else nums1[i - 1]
            nums1_right_min = float('inf') if i == m else nums1[i]
            nums2_left_max = float('-inf') if j == 0 else nums2[j - 1]
            nums2_right_min = float('inf') if j == n else nums2[j]

            # 5. 核心逻辑：判断交叉大小关系
            if nums1_left_max <= nums2_right_min and nums2_left_max <= nums1_right_min:
                # 找到正确的划分，根据总长度奇偶性计算中位数
                if (m + n) % 2 == 1:
                    return max(nums1_left_max, nums2_left_max)
                else:
                    return (max(nums1_left_max, nums2_left_max) + min(nums1_right_min, nums2_right_min)) / 2.0
            # 6. nums1_left_max 过大，说明切分线 i 在 nums1 中太靠右，需向左移
            elif nums1_left_max > nums2_right_min:
                right = i - 1
            # 7. nums2_left_max 过大，说明切分线 i 在 nums1 中太靠左，需向右移
            else:
                left = i + 1
        return 0.0

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        m, n = len(nums1), len(nums2)
        length = m + n
        # 1. 记下我们需要遍历到的最远的元素下标（无论奇偶）
        target = length // 2

        # 2. 只需要借助两个变量分别记录当前合并的最新值、以及它的前一个值
        left_val, right_val = -1, -1
        i = j = 0

        # 3. 走 target + 1 步停止
        for _ in range(target + 1):
            left_val = right_val
            # 注意边界条件：只有当 nums1 没越界且 (nums2 已越界或 nums1 的值 <= nums2) 时选取 nums1
            if i < m and (j >= n or nums1[i] <= nums2[j]):
                right_val = nums1[i]
                i += 1
            else:
                right_val = nums2[j]
                j += 1

        # 4. 根据长度奇偶返回
        if length % 2 == 0:
            return (left_val + right_val) / 2.0
        else:
            return float(right_val)

class Solution:
    def longestPalindrome(self, s: str) -> str:
        # 【模板：回文区间 DP】
        n = len(s)
        if n < 2:
            return s

        # dp[i][j] 表示 s[i:j+1] 是否是回文串
        dp = [[False] * n for _ in range(n)]
        # 初始化：所有长度为 1 的单个字符都是回文串
        for i in range(n):
            dp[i][i] = True

        max_len = 1
        begin = 0

        # 状态转移从短子串到长子串推进，因此按长度 L 进行枚举
        for L in range(2, n + 1):
            for i in range(n):
                # 由长度 L 和左边界 i 确定右边界 j
                j = L + i - 1
                # 【处理边界】如果右边界越界，退出当前循环
                if j >= n:
                    break

                # 【核心状态转移】首尾字符必须相等
                if s[i] != s[j]:
                    dp[i][j] = False
                else:
                    # 如果长度小于等于3（如 "aba"或"aa"），只要首尾相等就是回文，不需要查内部状态
                    if j - i <= 2:
                        dp[i][j] = True
                    else:
                        # 否则，取决于它去掉首尾后的内部子串 dp[i+1][j-1] 是否是回文
                        dp[i][j] = dp[i+1][j-1]

                # 打擂台记录
                if dp[i][j] and L > max_len:
                    max_len = L
                    begin = i

        return s[begin:begin + max_len]

class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ""
        # 外层循环遍历第一个字符串的首字符，将其视为列(column)
        for i in range(len(strs[0])):
            c = strs[0][i] 
            # 内层循环检查剩余所有字符串中相同列的字符
            for j in range(1, len(strs)):
                # 如果出现某个字符串长度不足，或者当前列字符发生不匹配
                if i == len(strs[j]) or strs[j][i] != c:
                    # 立即返回遇到不匹配之前的基准字符串前缀
                    return strs[0][:i]
        # 如果完全遍历完第一个字符串都没有中断，说明第一个字符串就是最长公共前缀
        return strs[0]

class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ""
        # 依据字典序对字母序列进行排序
        strs.sort()
        # 排序后，差异最大的无疑是首尾两个字符串
        # 因此只需要对比这两个字符串的公共前缀即可
        first, last = strs[0], strs[-1]
        i = 0
        while i < len(first) and i < len(last) and first[i] == last[i]:
            i += 1
        return first[:i]

class Solution:
    def isValid(self, s: str) -> bool:
        # 剪枝：如果字符串长度为奇数，不可能凑成一对，直接返回False
        if len(s) % 2 != 0:
            return False

        # 字典映射右括号到左括号，方便后续查表匹配
        # 为什么是 右->左？因为我们遍历时遇到右括号，需要知道它该和什么左括号匹配
        pairs = {
            ")": "(",
            "]": "[",
            "}": "{"
        }

        # 模拟栈，存储尚未被匹配的左括号
        stack = []

        for char in s:
            # 判断是否是右括号（即在字典的 keys 中）
            if char in pairs:
                # 取出栈顶元素准备匹配
                # 【坑】如果此时栈已经为空了，说明没有左括号可以和当前右括号匹配（例如输入 "]"），补一个特殊字符 '?' 防止越界
                top_element = stack.pop() if stack else "?"

                # 匹配失败：取出的栈顶左括号和字典中要求的不一致
                if pairs[char] != top_element:
                    return False
            else:
                # 没在字典中，说明是左括号（题目保证只包含六种字符）
                # 我们把左括号压入栈中
                stack.append(char)

        # 遍历完字符串后，如果栈为空，说明所有左括号都被匹配弹出，才是合法有效
        # 否则类似 "(" 的情况会留下未消的括号
        return not stack

class Solution:
    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        # 【模板：自底向上的链表递归】
        # 递归出口：只要有一个链表空了，直接返回另一个（无论其是否为空）
        if not list1:
            return list2
        if not list2:
            return list1

        # 不断缩小问题规模：选取当前较小头节点的链表作为保留方，它的 next 则是剩余部分与另一个完整链表合并后的结果
        if list1.val <= list2.val:
            list1.next = self.mergeTwoLists(list1.next, list2)
            return list1
        else:
            list2.next = self.mergeTwoLists(list1, list2.next)
            return list2

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []

        # 1. dfs(当前组合, 左括号可用剩余量, 右括号可用剩余量)
        def dfs(path, left, right):
            # 2. 终止条件：左右括号均消耗完，说明生成了一个合法的括号组合
            if left == 0 and right == 0:
                res.append(path)
                return

            # 3. 剪枝与分支：只要还有左括号可用，就可以放置左括号
            if left > 0:
                dfs(path + '(', left - 1, right)

            # 4. 核心在此：只有当剩余的右括号多于左括号时，才能放置右括号，保证组合的合法性
            if right > left:
                dfs(path + ')', left, right - 1)

        dfs("", n, n)
        return res

class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        # 边界控制
        if not lists:
            return None

        # 辅助函数：典型的归并两个有序序列至一条
        def mergeTwo(l1: ListNode, l2: ListNode) -> ListNode:
            dummy = ListNode()
            curr = dummy
            while l1 and l2:
                if l1.val < l2.val:
                    curr.next = l1
                    l1 = l1.next
                else:
                    curr.next = l2
                    l2 = l2.next
                curr = curr.next
            curr.next = l1 if l1 else l2
            return dummy.next

        # 分治主逻辑：将一堆任务一分为二直到不可分
        def divide_and_conquer(left: int, right: int) -> ListNode:
            # 叶子情况：无法再拆
            if left == right:
                return lists[left]
            # 越界防范（本题严谨控制下可能不触发）
            if left > right:
                return None

            mid = left + (right - left) // 2
            # 向下派发，让左右半区分别合并完毕
            l1 = divide_and_conquer(left, mid)
            l2 = divide_and_conquer(mid + 1, right)

            # 合并汇总（两表归并基建）
            return mergeTwo(l1, l2)

        return divide_and_conquer(0, len(lists) - 1)

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        # dp[i] 表示以 s[i] 结尾的最长有效括号子串的长度
        dp = [0] * n
        max_len = 0

        for i in range(1, n):
            if s[i] == ')':
                if s[i-1] == '(':
                    # 情况1：形如 ".....()"，最后两个形成一对
                    dp[i] = (dp[i-2] if i >= 2 else 0) + 2
                elif i - dp[i-1] > 0 and s[i - dp[i-1] - 1] == '(':
                    # 情况2：形如 "...((...))"，跳过内部完整的有效连串找匹配的左括号
                    # 如果找到了，就加上内部串的长度和这个左括号前面的有效串长度
                    dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 2] if i - dp[i-1] >= 2 else 0)

                max_len = max(max_len, dp[i])

        return max_len

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        # 栈内初始化一个 -1，作为"虚拟的"未匹配右括号，用于长度计算基准
        stack = [-1]
        max_len = 0

        for i, char in enumerate(s):
            if char == '(':
                # 左括号无脑入栈其索引
                stack.append(i)
            else:
                # 右括号尝试匹配
                stack.pop()
                if not stack:
                    # 如果栈空了，说明前面的全匹配完（或者此时是不合法右括号）
                    # 将当前的右括号索引入栈，作为新的边界计算基准
                    stack.append(i)
                else:
                    # 栈不空，当前索引减去栈顶存储的未匹配索引，即为这一段有效括号长度
                    max_len = max(max_len, i - stack[-1])

        return max_len

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        left = right = max_len = 0

        # 从左向右遍历，如果 right 数量超过 left说明右侧非法，清零
        for char in s:
            if char == '(':
                left += 1
            else:
                right += 1
            if left == right:
                max_len = max(max_len, 2 * right)
            elif right > left:
                left = right = 0

        left = right = 0
        # 从右向左遍历，如果 left 数量超过 right说明左侧非法，清零
        for char in reversed(s):
            if char == '(':
                left += 1
            else:
                right += 1
            if left == right:
                max_len = max(max_len, 2 * left)
            elif left > right:
                left = right = 0

        return max_len

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        # 【模板：变体条件约束的二分查找】
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = left + (right - left) // 2

            if nums[mid] == target:
                return mid

            # 【核心逻辑切分点】到底哪边是完全听话递增的？
            # 如果左边界的值小于等于中间位置的值，说明左半区完全没有任何悬崖倒挂，是标准的单调递增
            if nums[left] <= nums[mid]:
                # 由于此时左半区 [left, mid] 是严格听话的单调序列，我们可以百分之百信任它的范围判定
                # 如果目标在这个纯净区域的最小值和最大值之间
                if nums[left] <= target < nums[mid]:
                    right = mid - 1 # 安心地把右边界收缩到这里，搜索纯净区
                else:
                    left = mid + 1  # 否则，它就在对面那个含有断块的烂摊子里，转移战场
            else:
                # 反过来说，如果左半区存在悬崖，那说明右半区 [mid, right] 必然是完美纯净的递增单调区
                # 我们同样在这个听话的右半区做确信度极高的包裹测试
                if nums[mid] < target <= nums[right]:
                    left = mid + 1  # 确信它藏在这半边纯净区，收缩左边界
                else:
                    right = mid - 1 # 否则，去对面带有乱序断块的左半区重新玩

        # 最后夹逼不到，不存在
        return -1

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def binarySearch(isLeft):
            res = -1
            left, right = 0, len(nums) - 1
            while left <= right:
                mid = (left + right) // 2
                if nums[mid] < target:
                    left = mid + 1
                elif nums[mid] > target:
                    right = mid - 1
                else:
                    # 找到目标值，记录索引并尝试向边缘探测
                    res = mid
                    if isLeft:
                        # 寻找左边界，向左收缩区间
                        right = mid - 1
                    else:
                        # 寻找右边界，向右收缩区间
                        left = mid + 1
            return res

        # 两次调用，分别寻找左、右索引
        return [binarySearch(True), binarySearch(False)]

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)

        # 1. 第一轮遍历：尝试将每个数字 x 放到下标 x-1 的位置
        for i in range(n):
            # 条件：1 <= x <= n 且 x 还没在正确的位置上 (nums[x-1] != x)
            # 使用 while 循环是因为交换过来的新数字可能也需要安置
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                # 重点：swap(nums[i], nums[nums[i]-1])
                # 注意 Python 赋值顺序，直接写 a, b = b, a 较稳妥
                target_idx = nums[i] - 1
                nums[i], nums[target_idx] = nums[target_idx], nums[i]

        # 2. 第二轮遍历：寻找第一个位置不对的数
        for i in range(n):
            # 如果下标 i 存储的不是 i+1，说明 i+1 缺失
            if nums[i] != i + 1:
                return i + 1

        # 3. 特殊情况：如果 1~n 都在，缺失的就是 n+1
        return n + 1

class Solution:
    def rotate(self, matrix: List[List[int]]) -> None:
        """
        Do not return anything, modify matrix in-place instead.
        """
        n = len(matrix)
        # 步骤 1：水平翻转（上下对调）
        # 例如第一行和最后一行互换，第二行和倒数第二行互换
        for i in range(n // 2):
            for j in range(n):
                matrix[i][j], matrix[n - i - 1][j] = matrix[n - i - 1][j], matrix[i][j]

        # 步骤 2：主对角线翻转（左上到右下）
        # 仔细观察发现以对角线为轴，matrix[i][j] 与 matrix[j][i] 互换
        for i in range(n):
            for j in range(i):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

import math

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # 利用组合数学公式 C(N, K) = N! / (K! * (N-K)!)
        # 机器人无论怎么走，总共需要走到右下角必走 (m - 1) + (n - 1) = m + n - 2 步
        # 从 m + n - 2 步中选出 m - 1 步作为向下走的步数，其余自然是向右
        # 故答案为 C(m + n - 2, m - 1)
        return math.comb(m + n - 2, m - 1)

class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        for i in range(m):
            for j in range(n):
                # 起点，保持原值
                if i == 0 and j == 0:
                    continue
                # 第一行，只能从左边转移过来
                elif i == 0:
                    grid[i][j] += grid[i][j-1]
                # 第一列，只能从上面转移过来
                elif j == 0:
                    grid[i][j] += grid[i-1][j]
                # 内部节点，取左侧和上侧的较小值加上当前格子的值
                else:
                    grid[i][j] += min(grid[i-1][j], grid[i][j-1])

        return grid[-1][-1]

class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp = [0] * n

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    dp[j] = grid[i][j]
                elif i == 0:
                    # 第一行，只能通过左边的状态推导
                    dp[j] = dp[j-1] + grid[i][j]
                elif j == 0:
                    # 第一列，只能通过上一行的状态推导 (此时 dp[j] 即为上一行当前列的值)
                    dp[j] = dp[j] + grid[i][j]
                else:
                    # dp[j] 是上一行的值（上），dp[j-1] 是左边的值
                    dp[j] = min(dp[j], dp[j-1]) + grid[i][j]

        return dp[-1]

class Solution:
    def mySqrt(self, x: int) -> int:
        if x == 0:
            return 0

        # 答案一定在 1 到 x 之间
        left, right = 1, x
        ans = 0

        while left <= right:
            # 防止整型溢出的中间值求法
            mid = left + (right - left) // 2

            if mid <= x // mid:
                # mid^2 <= x，说明 mid 可能是答案，记录答案
                # 由于我们要找向下取整的平方根，我们要尽量找大的，因此继续去右半区间探索
                ans = mid
                left = mid + 1
            else:
                # mid^2 > x，说明 mid 太大了，去左侧找
                right = mid - 1

        return ans

class Solution:
    def mySqrt(self, x: int) -> int:
        if x == 0:
            return 0

        # 初始猜测值设为 x本身，迭代公式为: t_{n+1} = (t_n + x / t_n) / 2
        r = x
        while r > x // r:
            # 当猜测值过大时，利用牛顿法迭代更新趋近于真实根
            r = (r + x // r) // 2

        # 由于每次向下取整，最后收敛时保证 r^2 <= x
        return r

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)

        # 若有任一字符串为长度0的空串，所需操作数必为另一字符串长（只能全做增或全做删）
        if m == 0 or n == 0:
            return m + n

        # 声明 dp 二维结构：(m+1) 行 (n+1) 列
        # 其中 dp[i][j] 的含义为把 word1[0..i-1] 变为 word2[0..j-1] 最小步数
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Base Case 1：将长度为0的空字串转为任一单词，只能不断插入，操作数=列索引
        for j in range(n + 1):
            dp[0][j] = j

        # Base Case 2：任一单词字串转为空串，只能不断删除，操作数=行索引
        for i in range(m + 1):
            dp[i][0] = i

        # 核心算法（双层 DP）：用子问题迭代推算主问题
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # 【重要分支】：比较将要处理且位于两串末尾位置的字符（即下标-1）
                if word1[i - 1] == word2[j - 1]:
                    # 如果最新比对的尾字符相同，则直接继承减去该字符前两个子串的最佳操作数
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    # 如果不同，我们仅剩三种合法出路，择其最小代价执行并且加1次本次实操：
                    # (1) dp[i - 1][j]: 把word1当前末端字去掉，让前面的自个去匹配，由于删除了就是 + 1
                    # (2) dp[i][j - 1]: 在word1强插目标字对其，剩下的前缀同目标串去头对应，即插入 + 1
                    # (3) dp[i - 1][j - 1]: 强行把两边替换为一致的（等效于双去头），代价 + 1
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

        return dp[m][n]

class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        # 1. 虚拟头节点：处理头节点可能被删除的边界情况
        dummy = ListNode(-1)
        dummy.next = head
        # 2. cur 表示「当前确定的不重复节点序列的最后一个节点」
        cur = dummy

        while cur.next and cur.next.next:
            # 3. 发现重复元素段的开头
            if cur.next.val == cur.next.next.val:
                # 记录重复值
                val = cur.next.val
                # 4. 跳过所有等于该重复值的节点
                while cur.next and cur.next.val == val:
                    cur.next = cur.next.next
            else:
                # 5. 无重复，安心推进扩散
                cur = cur.next

        return dummy.next

class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        # 边界条件处理
        if not head:
            return head

        # 游标指针
        curr = head
        # 遍历链表直到没有下一个节点
        while curr.next:
            # 如果当前节点的值等同于下一个节点，则跳过下一个节点（删除操作）
            if curr.val == curr.next.val:
                curr.next = curr.next.next
            else:
                # 否则游标正常前移
                curr = curr.next

        return head

class Solution:
    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:
        # 将 nums2 全面替换进 nums1 的占位区域 (从索引 m 起)
        nums1[m:] = nums2
        # 调用内置的 Timsort 原地排序
        nums1.sort()

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        # 使用中序遍历：只需要保证当前遍历的节点值一定大于前一个访问的节点值即可
        self.pre = float('-inf')  # 记录前一个访问的节点对应的值

        def inorder(node):
            if not node:
                return True
            # 先往左走
            if not inorder(node.left):
                return False

            # 处理当前节点：值应当严格大于前一个节点的值
            if node.val <= self.pre:
                return False
            self.pre = node.val  # 更新前驱节点值

            # 再往右走
            return inorder(node.right)

        return inorder(root)

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def helper(node, lower, upper):
            if not node:
                return True
            val = node.val
            # 当前节点的值必须落在合法的 [lower, upper] 区间内
            if val <= lower or val >= upper:
                return False

            # 递归往左子树看，当前节点的值成为了左子树所有节点的上限 (upper)
            # 递归往右子树看，当前节点的值成为了右子树所有节点的下限 (lower)
            return helper(node.left, lower, val) and helper(node.right, val, upper)

        return helper(root, float('-inf'), float('inf'))

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True

        def dfs(left: Optional[TreeNode], right: Optional[TreeNode]) -> bool:
            # 两个节点都为空，对称
            if not left and not right:
                return True
            # 只有一个为空或值不相等，不对称
            if not left or not right or left.val != right.val:
                return False
            # 递归比较：左子树的左节点与右子树的右节点比较（外侧）；左子树的右节点与右子树的左节点比较（内侧）
            return dfs(left.left, right.right) and dfs(left.right, right.left)

        return dfs(root.left, root.right)

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True

        # 队列中始终保存一对需要比较镜像的节点
        queue = collections.deque([root.left, root.right])

        while queue:
            left = queue.popleft()
            right = queue.popleft()

            if not left and not right:
                continue
            if not left or not right or left.val != right.val:
                return False

            # 注意入队顺序：外侧节点配对，内侧节点配对
            queue.append(left.left)
            queue.append(right.right)
            queue.append(left.right)
            queue.append(right.left)

        return True

class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        # 边界条件，也是递归的出口，空节点的高度为 0
        if not root:
            return 0

        # 递归计算左子树和右子树的最大深度
        left_depth = self.maxDepth(root.left)
        right_depth = self.maxDepth(root.right)

        # 当前节点在树中的深度为其左右子节点最大深度加 1（加上自身）
        return max(left_depth, right_depth) + 1

class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        queue = collections.deque([root])
        depth = 0

        # 外层循环控制深度（一层一层的去处理）
        while queue:
            # current_size 记录当前层的节点数
            current_size = len(queue)
            # 将本层所有的节点全部出队，并把它们的孩子入队以备下层使用
            for _ in range(current_size):
                node = queue.popleft()
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            # 经过一层的处理，深度计数加 1
            depth += 1

        return depth

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def get_height(node: Optional[TreeNode]) -> int:
            if not node:
                return 0

            # 分别获取左子树和右子树的高度
            left_height = get_height(node.left)
            # 如果左子树已经不平衡（返回了 -1），短路直接向上层抛出 -1
            if left_height == -1:
                return -1

            right_height = get_height(node.right)
            # 如果右子树不平衡（返回了 -1），同样短路向上层抛出
            if right_height == -1:
                return -1

            # 判断当前节点的左右子树高度差，如果不满足平衡条件，返回 -1
            if abs(left_height - right_height) > 1:
                return -1

            # 如果平衡，返回当前树的最大高度，供上层继续计算
            return max(left_height, right_height) + 1

        return get_height(root) != -1

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True

        def height(node: Optional[TreeNode]) -> int:
            if not node:
                return 0
            return max(height(node.left), height(node.right)) + 1

        # 当前节点平衡，且左子树平衡、右子树也平衡
        # 缺点：这里的 height 会被频繁重复调用，父节点调了一次，其所有子节点又会被重新作为根计算高度
        return abs(height(root.left) - height(root.right)) <= 1 and \
               self.isBalanced(root.left) and \
               self.isBalanced(root.right)

from collections import deque

class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        if not root:
            return False

        # 初始化队列，队列元素为元组：(当前节点, 还需要凑齐的数值)
        queue = deque([(root, targetSum - root.val)])

        while queue:
            # 每次弹出一个节点及其对应的剩余目标和
            curr_node, remain_sum = queue.popleft()

            # 如果当前是叶子节点，并且剩余目标和恰好由于本节点被减去而归零
            if not curr_node.left and not curr_node.right and remain_sum == 0:
                return True

            # 如果有左子节点，将其压入队列，同时更新需要的剩余目标和
            if curr_node.left:
                queue.append((curr_node.left, remain_sum - curr_node.left.val))
            # 如果有右子节点，执行相同逻辑
            if curr_node.right:
                queue.append((curr_node.right, remain_sum - curr_node.right.val))

        # 遍历尽所有路径都没找到，返回 False
        return False

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        max_profit = 0
        n = len(prices)

        # 外层枚举买入时机
        for i in range(n):
            # 内层枚举卖出时机（卖出必然在买入的后面发生）
            for j in range(i + 1, n):
                # 计算两天的差额
                profit = prices[j] - prices[i]
                # 更新最大收益
                if profit > max_profit:
                    max_profit = profit

        return max_profit

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        profit = 0
        for i in range(1, len(prices)):
            # 贪心策略：只要有利润就赚
            # 实际上是将所有上升区间的差值累加，相当于在低点买入高点卖出
            if prices[i] > prices[i - 1]:
                profit += prices[i] - prices[i - 1]
        return profit

class Solution:
    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        def dfs(node, current_sum):
            # 1. 递归边界：空节点返回 0（不贡献和）
            if not node:
                return 0

            # 2. 计算当前节点形成的路径数值
            # 规则：前序数值 * 10 + 当前节点值
            current_sum = current_sum * 10 + node.val

            # 3. 叶子节点判断：如果左右孩子都为空，说明路径走到底，返回当前数值
            if not node.left and not node.right:
                return current_sum

            # 4. 递归计算左右子树的所有路径之和并汇总
            return dfs(node.left, current_sum) + dfs(node.right, current_sum)

        return dfs(root, 0)

from collections import deque

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        word_set = set(wordDict)
        # 队列中存的是探索下标起点
        queue = deque([0])
        # visited 数组作记忆化。含义是：只要考察过这个起点向后所有的切分可能，就记录下来，后面再去走就是纯兜圈子
        visited = set()

        while queue:
            start = queue.popleft()
            # 搜通关了，走到底了，表示能无损拼出来
            if start == len(s):
                return True

            # 如果这扇门早就推过证明走不通死胡同了，快跑别进去
            if start in visited:
                continue
            visited.add(start)

            # 尝试在这个位置，从字典里所有可能的长度去截取后面的一段字符匹配
            for end in range(start + 1, len(s) + 1):
                # 如果可以从 start 跳到 end，那么把 end 压入队列作为下一跳考察地
                if s[start:end] in word_set:
                    queue.append(end)

        return False

class Solution:
    def preorderTraversal(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        res = []
        # 栈初始压入根节点
        stack = [root]
        while stack:
            # 弹出栈顶元素并访问（因为是前序，先访问中间节点）
            node = stack.pop()
            res.append(node.val)
            # 注意：因为栈是先进后出 (LIFO)
            # 我们需要左子树先被处理，所以必须先把右子树压入栈，再压入左子树！
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)
        return res

from collections import OrderedDict

class LRUCache(OrderedDict):
    def __init__(self, capacity: int):
        # 初始化继承的内置类
        super().__init__()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self:
            return -1
        # 关键操作：取过即新，利用内置 move_to_end 快速完成位移操作
        self.move_to_end(key)
        return self[key]

    def put(self, key: int, value: int) -> None:
        if key in self:
            # 按语义更新活跃度
            self.move_to_end(key)
        self[key] = value
        # 关键分支：溢出淘汰。在 OrderedDict 中 last=False 表现为 FIFO，即淘汰头部最旧
        if len(self) > self.capacity:
            self.popitem(last=False)

class Solution:
    def reverseWords(self, s: str) -> str:
        # 1. split() 会自动按空格切分，并跳过空字符串（即处理了多余空格）
        words = s.split()
        # 2. 翻转列表 [::-1] 或 words.reverse()
        # 3. 使用单个空格连接并返回
        return " ".join(words[::-1])

class Solution:
    def reverseWords(self, s: str) -> str:
        # 1. 去除首尾空格
        s = s.strip()
        res = []
        i = j = len(s) - 1

        # 2. 从后向前搜索每一段非空字符
        while i >= 0:
            while i >= 0 and s[i] != ' ': i -= 1 # 搜索首个空格
            res.append(s[i + 1: j + 1])      # 提取单词并入队
            while i >= 0 and s[i] == ' ': i -= 1 # 跳过单词间的重复空格
            j = i                             # 准备搜索下一个单词

        return ' '.join(res)

class Solution:
    def __init__(self):
        # 1. 主栈：存储真实数据
        self.stack = []
        # 2. 辅助栈：同步存储当前阶段的最小值
        self.min_stack = []

    def push(self, val: int) -> None:
        self.stack.append(val)
        # 3. 更新 min_stack：如果辅助栈为空，直接入栈；
        # 否则比较新值与当前最小值，压入较小的一个
        if not self.min_stack:
            self.min_stack.append(val)
        else:
            # 保证 min_stack 与 stack 元素一一对应
            self.min_stack.append(min(val, self.min_stack[-1]))

    def pop(self) -> None:
        # 4. 同步弹出，保持两栈长度一致
        self.stack.pop()
        self.min_stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        # 5. 直接返回辅助栈顶即为全栈最小，时间复杂度 O(1)
        return self.min_stack[-1]

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1
        # 采用左右逼近的方式，循环结束时 left == right
        while left < right:
            mid = (left + right) // 2
            # 如果当前位置比右边一个小，说明我们处在“上坡”路段。
            # 顺着坡往上走（向右），必然会遇到一个峰值（因为边界是 -∞）
            if nums[mid] < nums[mid + 1]:
                left = mid + 1
            # 如果当前位置比右边一个大，说明我们处在“下坡”路段。
            # 或者当前位置本身就是封顶。所以向左收缩查找，左边必然有峰值
            else:
                right = mid

        # 收敛时，left 和 right 重合，即抵达了峰顶
        return left

class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        # 1. 内置分割将字符串切至 list
        v1_list = version1.split('.')
        v2_list = version2.split('.')

        # 2. 选择较长段数量进行遍历比对
        max_len = max(len(v1_list), len(v2_list))

        for i in range(max_len):
            # 3. 长度不齐默认转成值为 0 的参与对线
            x = int(v1_list[i]) if i < len(v1_list) else 0
            y = int(v2_list[i]) if i < len(v2_list) else 0

            if x > y:
                return 1
            elif x < y:
                return -1

        return 0

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        counts = {}
        # 遍历数组，累计频率
        for num in nums:
            counts[num] = counts.get(num, 0) + 1
            # 由于题目保证多数元素一定存在，只要数量超过一半即可返回
            if counts[num] > len(nums) // 2:
                return num
        return -1

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        # 直接排序（Python 内部为 Timsort，空间复杂度为 O(N)，这里假设原地排序为 O(1)）
        nums.sort()
        # 多数派元素超过一半，必定占据了中位数位置
        return nums[len(nums) // 2]

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        count = 0
        candidate = None

        for num in nums:
            # 当 count 为 0 时，说明之前的元素都两两抵消了，重新假设当前元素是众数
            if count == 0:
                candidate = num
            # 当前元素等同候选众数，势力壮大 (count+1)；否则互相抵消损耗 (count-1)
            count += (1 if num == candidate else -1)

        return candidate

class Solution:
    def largestNumber(self, nums: List[int]) -> str:
        # 将数字全部转成字符串以便拼接和比较
        strs = [str(num) for num in nums]

        # 自定义比较规则（Python3 中 key=cmp_to_key 的经典用法）
        # 若 x+y 大于 y+x，说明 x 应该排在前面
        import functools
        def cmp(x, y):
            if x + y > y + x:
                return -1 # x排在前面
            elif x + y < y + x:
                return 1
            else:
                return 0

        strs.sort(key=functools.cmp_to_key(cmp))
        ans = "".join(strs)

        # 特殊情况处理：由于数组可能全是0（如 [0,0]），排序后会得到 "00"
        # 直接剥离前导零或转整数再转回判断比较麻烦，所以如果开头的是 "0" 就是 "0"
        return "0" if ans[0] == "0" else ans

class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        ans = []

        # 1. 定义带有层深信息的递归
        def dfs(node: Optional[TreeNode], depth: int):
            if not node:
                return
            # 2. 因为优先访问右孩子，所以首次层深等于结果集长度时，必然是该层最靠右的节点
            if depth == len(ans):
                ans.append(node.val)

            # 3. 压层递归：优先右，其次左，如此每一层中右边靠外的先被记录进总表
            dfs(node.right, depth + 1)
            dfs(node.left, depth + 1)

        dfs(root, 0)
        return ans

class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []

        ans = []
        # 1. 初始化队列，首入根节点
        queue = collections.deque([root])

        while queue:
            size = len(queue)

            for i in range(size):
                node = queue.popleft()
                # 2. 定位到当前层最后一个出列的节点，就是右侧最终视图
                if i == size - 1:
                    ans.append(node.val)

                # 3. 继续扩展队列宽度供下层拉平横向遍历
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

        return ans

from collections import deque

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        # 【模板：二维网格一层层外推的 BFS】
        if not grid:
            return 0

        rows, cols = len(grid), len(grid[0])
        islands = 0

        def bfs(r, c):
            # 初始化双端队列并塞入爆炸原点
            queue = deque([(r, c)])
            # 【细节】放入队列的同时立即将其沉没，防止被其他 BFS 源头重叠扫描导致死循环
            grid[r][c] = "0"

            # 标准位移向量：四个方向
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

            while queue:
                # 不用管按不按层了，纯粹是为了清空全部相关块
                curr_r, curr_c = queue.popleft()

                for dr, dc in directions:
                    nr, nc = curr_r + dr, curr_c + dc
                    # 【越界与水域判断】仅在这个新的派生坐标是陆地的情况下入队
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "1":
                        queue.append((nr, nc))
                        # 在这里第一时间标记已访问（至关重要），若在这不标记，会被其他邻居重复推入队
                        grid[nr][nc] = "0"

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == "1":
                    islands += 1
                    bfs(r, c)

        return islands

import random
class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        # 将“第 k 大”转换为“排序后的第 target 下标”（0 索引）
        target = len(nums) - k

        def quick_select(left, right):
            # 关键优化：加入洗牌思维随机抽取基准，防止退化
            pivot_index = random.randint(left, right)
            nums[pivot_index], nums[right] = nums[right], nums[pivot_index]

            # 指针 p 永远充当“所有比 pivot 小的连续集体的右边界”
            p = left
            for i in range(left, right):
                if nums[i] < nums[right]:
                    nums[i], nums[p] = nums[p], nums[i]
                    p += 1
            # 把压轴换回到它的绝对顺位（它前面都小，后面都大） 
            nums[p], nums[right] = nums[right], nums[p]

            # 关键分支：枢轴归位后检查其是否恰是我们要找的人
            if p == target:
                return nums[p]
            elif p < target:
                # 不足目标位置，目标肯定在右边阵营，舍弃左半图
                return quick_select(p + 1, right)
            else:
                # 超过目标位置，只能继续在左侧挖掘
                return quick_select(left, p - 1)

        return quick_select(0, len(nums) - 1)

import heapq
class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        min_heap = []

        # N 次遍历，所有元素依次尝试入堆进场
        for num in nums:
            heapq.heappush(min_heap, num)
            # 关键分支：超出容积 K 的红线限制？清出场内的倒数第一劣汰者
            if len(min_heap) > k:
                heapq.heappop(min_heap)

        # 处理完毕后，堆里沉着的恰好是排名最高的前K人，最脆弱的堆顶就是守门员第K大
        return min_heap[0]

class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        dp = [[0] * n for _ in range(m)]
        max_side = 0

        for i in range(m):
            for j in range(n):
                if matrix[i][j] == '1':
                    # 边界上的正方形，最大边长只能是 1
                    if i == 0 or j == 0:
                        dp[i][j] = 1
                    else:
                        # 核心状态转移：当前格子受限于左边、上边、左上角三个正方形的最小边长
                        # 木桶效应，只有三个方向都能扩展，当前才能形成大正方形
                        dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                    # 维护全局最大边长
                    max_side = max(max_side, dp[i][j])

        return max_side * max_side

class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0

        m, n = len(matrix), len(matrix[0])
        dp = [0] * (n + 1)
        max_side = 0
        prev = 0 # 记录左上角的值 (即 dp[i-1][j-1])

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                temp = dp[j] # 当前行的旧值，即下一次迭代的左上角的值
                if matrix[i-1][j-1] == '1':
                    # 状态转移：dp[j-1] 是左边的值，dp[j]是上边的值，prev是左上角的值
                    dp[j] = min(dp[j-1], dp[j], prev) + 1
                    max_side = max(max_side, dp[j])
                else:
                    # 注意如果为 '0' 必须要清空，因为复用了一维数组
                    dp[j] = 0
                prev = temp

        return max_side * max_side

from collections import deque
class Solution:
    def invertTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root:
            return None

        # 建立 BFS 排队的传送带，起点先摆上去
        queue = deque([root])

        while queue:
            # 拿到传送带上吐露出的最先干活节点
            node = queue.popleft()

            # 干活本质：不问三七二十一调换两端分支把手上这层做个镜像
            node.left, node.right = node.right, node.left

            # 继续把未尽事宜排队安排给下层
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        return root

class Solution:
    def calculate(self, s: str) -> int:
        # 栈，用于存储需要最终求和的各个部分（加减法的部分）
        stack = []
        # pre_op 记录遍历到的当前数字前最近遇到的操作符，初始默认是 '+'
        pre_op = '+'
        num = 0

        for i, char in enumerate(s):
            # 如果是数字字符，累加计算完整的数值
            if char.isdigit():
                num = num * 10 + int(char)

            # 如果遇到操作符，或者已经遍历到字符串末尾，需要把前面的 num 配合 pre_op 处理入栈
            if char in '+-*/' or i == len(s) - 1:
                if pre_op == '+':
                    stack.append(num)
                elif pre_op == '-':
                    # 减法转化为加上负数
                    stack.append(-num)
                elif pre_op == '*':
                    # 乘法优先级高，直接弹出栈顶与当前数相乘后重新入栈
                    stack.append(stack.pop() * num)
                elif pre_op == '/':
                    # 除法优先级高，保留整数部分（注意 Python 负数整除由于向下取整会有坑，需使用 int() 截取向零取整）
                    stack.append(int(stack.pop() / num))

                # 更新 pre_op 为当前遇到的操作符，重置数字以便解析下一个数
                pre_op = char
                num = 0

        # 所有乘除都已经在遍历中处理完毕，栈内只剩下需要加和的各项
        return sum(stack)

class Solution:
    def calculate(self, s: str) -> int:
        res = 0        # 记录已确定的总和
        last_num = 0   # 记录最后一个待确定的项（等价于栈顶元素）
        num = 0
        pre_op = '+'

        for i, char in enumerate(s):
            if char.isdigit():
                num = num * 10 + int(char)

            if char in '+-*/' or i == len(s) - 1:
                if pre_op == '+' or pre_op == '-':
                    # 遇到加减法，说明之前的 last_num 可以确切地加到总和 res 中了
                    res += last_num
                    # 更新 last_num，注意携带正负号
                    last_num = num if pre_op == '+' else -num
                elif pre_op == '*':
                    # 遇到乘法，历史上的 last_num 还没算完，先与当前数相乘
                    last_num = last_num * num
                elif pre_op == '/':
                    # 遇到除法，同理与当前数进行向零取整的除法即可
                    last_num = int(last_num / num)

                pre_op = char
                num = 0

        # 最后跳出循环时，不要忘记把剩余的一个待确定项 last_num 加入最终总和
        return res + last_num

class MyQueue:
    def __init__(self):
        # in_stack 负责处理入队操作，天然为后进先出 (LIFO)
        self.in_stack = []
        # out_stack 负责出队。当它有元素时，直接弹出；无元素时，从 in_stack 倒腾过来，实现 LIFO -> FIFO
        self.out_stack = []

    def push(self, x: int) -> None:
        # 入队直接放入 in_stack
        self.in_stack.append(x)

    def _transfer(self):
        # 核心逻辑：惰性倾倒。只要 out_stack 为空，就将 in_stack 中的元素全部倒过来
        # 这一过程时间复杂度均摊为 O(1)
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def pop(self) -> int:
        self._transfer()
        return self.out_stack.pop()

    def peek(self) -> int:
        self._transfer()
        return self.out_stack[-1]

    def empty(self) -> bool:
        return not self.in_stack and not self.out_stack

class Solution:
    def isPalindrome(self, head: Optional[ListNode]) -> bool:
        vals = []
        curr = head
        # 将链表节点值拷贝到数组中
        while curr:
            vals.append(curr.val)
            curr = curr.next

        # 双指针判断数组是否回文
        left, right = 0, len(vals) - 1
        while left < right:
            if vals[left] != vals[right]:
                return False
            left += 1
            right -= 1

        return True

import collections

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        if not nums:
            return []

        # 1. q存储的是nums的下标，为了方便判断队头元素是否滑出窗口
        q = collections.deque()
        res = []

        for i, val in enumerate(nums):
            # 2. 维护队列单调性：新来的元素比队尾大，说明队尾元素永远不可能成为最大值了，直接弹出
            while q and nums[q[-1]] <= val:
                q.pop()
            q.append(i)

            # 3. 维护窗口大小：判断队头元素是否已经滑出当前窗口（下标 <= i - k）
            if q[0] <= i - k:
                q.popleft()

            # 4. 记录答案：当窗口形成后（即索引到了 k - 1 及以上），队头元素就是当前窗口最大值
            if i >= k - 1:
                res.append(nums[q[0]])

        return res

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        if not matrix or not matrix[0]:
            return False
        m, n = len(matrix), len(matrix[0])

        # 从右上角开始作为起点
        # 这里的元素具有特殊性：它是当前行最大的，是当前列最小的
        row, col = 0, n - 1

        while row < m and col >= 0:
            if matrix[row][col] == target:
                return True
            elif matrix[row][col] > target:
                # 如果右上角元素比 target 大，说明这一列剩下的元素更不可能等于 target
                # 因为向下的元素越来越大。所以向左移动，排除当前列。
                col -= 1
            else:
                # 如果右上角元素比 target 小，说明这一行剩下的元素更不可能等于 target
                # 以为左边的元素越来越小。所以向下移动，排除当前行。
                row += 1

        return False

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        # 遍历每一行执行二分查找
        import bisect
        for row in matrix:
            # bisect_left 找目标位置，需要在合法范围并且值严格相等做校验
            idx = bisect.bisect_left(row, target)
            if idx < len(row) and row[idx] == target:
                return True
        return False

class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        # slow 指针指向下一个准备放置非 0 元素的位置
        slow = 0
        # fast 遍历整个数组寻找非 0 元素
        for fast in range(len(nums)):
            if nums[fast] != 0:
                # 将非 0 元素放到 slow 的位置，并让 slow 前进
                nums[slow] = nums[fast]
                slow += 1
        # 所有的非 0 元素都已放好，将 slow 指针及以后的位置补 0
        for i in range(slow, len(nums)):
            nums[i] = 0

class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        slow = 0
        for fast in range(len(nums)):
            if nums[fast] != 0:
                # 通过交换，非 0 元素前移，0 元素后移，自然完成补 0 操作
                nums[slow], nums[fast] = nums[fast], nums[slow]
                slow += 1

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # tails 数组维护长度为 i+1 的最长递增子序列的最小结尾元素
        # 核心思想是如果要使上升序列尽可能长，结尾元素要尽可能小
        tails = []
        for num in nums:
            # 二分查找 num 在 tails 中的位置（第一个大于等于 num 的位置）
            left, right = 0, len(tails) - 1
            while left <= right:
                mid = left + (right - left) // 2
                if tails[mid] < num:
                    left = mid + 1
                else:
                    right = mid - 1

            # 如果 num 大于 tails 中所有元素，说明它可以作为更长子序列的结尾
            if left == len(tails):
                tails.append(num)
            # 否则，它比当前同长度子序列的结尾元素更小，更新底座以获得后续更多成长潜力
            else:
                tails[left] = num

        # tails 数组并不是真正的 LIS（虽然长度一致），其长度即为所求答案
        return len(tails)

class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        if not nums:
            return 0

        # 初始化 DP 数组，每个元素自身可以构成长度至少为 1 的子序列
        dp = [1] * len(nums)
        max_len = 1

        # 外层循环：确定以 nums[i] 作为子序列结尾时的状态
        for i in range(1, len(nums)):
            # 内层循环：查看 i 之前的所有元素 j，尝试拼接
            for j in range(i):
                # 只有当 nums[i] 严格大于前面的元素时，才能拼接成长并构成上升序列
                if nums[i] > nums[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
            # 动态维护全局最大长度
            max_len = max(max_len, dp[i])

        return max_len

class Solution:
    def decodeString(self, s: str) -> str:
        stack = []
        res = ""
        multi = 0

        for c in s:
            if c == '[':
                # 遇到左括号，入栈保存当前状态，以便后续回溯拼接
                stack.append((multi, res))
                # 重置状态，开始记录括号内的新字符串和乘数
                multi, res = 0, ""
            elif c == ']':
                # 遇到右括号，出栈上一个状态
                cur_multi, last_res = stack.pop()
                # last_res 是括号前的字符串，res 是当前括号内的字符串
                res = last_res + cur_multi * res
            elif '0' <= c <= '9':
                # 处理多位数字
                multi = multi * 10 + int(c)
            else:
                # 单纯字母直接拼接
                res += c

        return res

class Solution:
    def rand10(self) -> int:
        while True:
            # (rand7() - 1) 产生 0-6 均匀分布
            # 规律：(RandX() - 1) * X + RandX() 可生成等概率的 1 到 X*X 分布
            # 此处可以生成等概率的 1-49 这个区间的数字
            idx = (rand7() - 1) * 7 + rand7()

            # 大于 40 的值只有 9 个，如果直接拒绝掉并重新生成，
            # 这里由于 40 是 10 的倍数，正好能在 1..40 间进行等概率地按组分配
            if idx <= 40:
                # 1~40 取模 10 得到 0~9，加 1 则映射为 1~10 的均匀分布
                return 1 + (idx - 1) % 10

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        # pre_dict 记录前缀和出现的次数，初始化 {0: 1}
        # 为什么要初始化 pre_dict[0] = 1？ 
        # 因为如果当前前缀和本身就等于 k (即 pre[i] - k = 0)，说明从头到当前位置的子数组和为 k
        # 此时需要它能正常构成一次匹配
        pre_dict = {0: 1}
        pre_sum = 0 # 记录到当前的累加和
        count = 0

        for num in nums:
            pre_sum += num
            # 如果在当前位置以前出现过和为 pre_sum - k 的前缀，说明中间被截取的这一段和就刚好是 k
            if pre_sum - k in pre_dict:
                count += pre_dict[pre_sum - k]

            # 将当前产生的前缀和登记到哈希表，供以后的数字使用
            # 务必在判断完成后再更新当前前缀和字典（否则如果 k=0 会把自己本位置匹配算进去）
            pre_dict[pre_sum] = pre_dict.get(pre_sum, 0) + 1

        return count

class Solution:
    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0

        max_area = 0
        m, n = len(grid), len(grid[0])

        def dfs(i: int, j: int) -> int:
            # 越界检查、或是已经是水（值为 0），则当前格子对面积贡献为 0
            if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == 0:
                return 0

            # 破坏性遍历（沉岛思想）：将走过的1变为0，避免再次遍历进入死循环
            grid[i][j] = 0

            # 当前陆地贡献连通面积为 1，加上上下左右四个方向散发继续联接周围陆地得到的大小
            return 1 + dfs(i-1, j) + dfs(i+1, j) + dfs(i, j-1) + dfs(i, j+1)

        # 遍历所有网格，寻找潜在岛屿
        for i in range(m):
            for j in range(n):
                # 一旦找到一块没碰过的陆地，即代表挖到了一个新的小岛群
                if grid[i][j] == 1:
                    # 获取一次独立完整的岛屿探索结果大小
                    area = dfs(i, j)
                    max_area = max(max_area, area)

        return max_area

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        # left 和 right 定义了搜索区间的边界：[left, right]
        left, right = 0, len(nums) - 1

        # 当 left <= right 时，区间内是有元素的，需要继续搜索
        while left <= right:
            # 防止 left + right 导致的整型溢出（虽然 Python 这里不用担心，但属于工程好习惯）
            mid = left + (right - left) // 2

            if nums[mid] == target:
                # 找到目标值，直接返回下标
                return mid
            elif nums[mid] < target:
                # 目标值在右半部分，更新左边界，因为 mid 已经不仅是在目标值范围内了
                left = mid + 1
            else:
                # 目标值在左半部分，更新右边界
                right = mid - 1

        # 遍历完毕未找到
        return -1

class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        m, n = len(nums1), len(nums2)
        # dp[i][j] 表示以 nums1[i-1] 和 nums2[j-1] 结尾的公共子数组长度
        # 额外加1的长度为了处理空前缀边界，避免繁琐的 if 判断
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        ans = 0

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # 必须末尾字符相同才能继续连续
                if nums1[i - 1] == nums2[j - 1]:
                    # 在前面已经连续的基础上加1
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    ans = max(ans, dp[i][j])
                else:
                    # 不相同则直接断掉连续性，从 0 重新开始（初始化为 0 所以无需额外赋值）
                    dp[i][j] = 0

        return ans

class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        m, n = len(nums1), len(nums2)
        # 仅保留一行信息
        dp = [0] * (n + 1)
        ans = 0

        for i in range(1, m + 1):
            # 这里必须倒序遍历 j！因为 dp[j] 依赖左上角的旧值 dp[i-1][j-1]
            # 如果正序遍历，dp[j-1] 已经被当前这一行覆盖更新了
            for j in range(n, 0, -1):
                if nums1[i - 1] == nums2[j - 1]:
                    dp[j] = dp[j - 1] + 1
                    ans = max(ans, dp[j])
                else:
                    dp[j] = 0

        return ans

class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        def maxLength(addA: int, addB: int, length: int) -> int:
            ret = k = 0
            for i in range(length):
                if nums1[addA + i] == nums2[addB + i]:
                    k += 1
                    ret = max(ret, k)
                else:
                    k = 0
            return ret

        n, m = len(nums1), len(nums2)
        ans = 0
        # 第一种情况：nums1 滑过 nums2
        for i in range(n):
            length = min(m, n - i)
            ans = max(ans, maxLength(i, 0, length))
        # 第二种情况：nums2 滑过 nums1
        for i in range(m):
            length = min(n, m - i)
            ans = max(ans, maxLength(0, i, length))
        return ans

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        # 初始化 DP 表，行和列多加 1 为了处理空字符串这类的 Base Case
        # dp[i][j] 表示 text1 的前 i 个字符和 text2的前 j 个字符的最长公共子序列长度
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # 核心算法（双层 DP）：用子问题的最优解不断迭代出最终解
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                # 【重要分支】：比较将要处理且位于两串末尾位置的字符
                if text1[i - 1] == text2[j - 1]:
                    # 相等：说明找到了新公共字符，则在两者各自去掉该末尾字符的匹配解（左上角的值）基础上加一
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    # 不等：说明当前这两个字符不可能同时出现在 LCS 中。
                    # 因此，最优解必定来自或不要 text1 末位对应结果，或不要 text2 末位对应结果，取局部最大值。
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        # 空间优化点：让列数为两个字符串中的较小值，以尽量压缩一维数组长度
        if m < n:
            return self.longestCommonSubsequence(text2, text1)

        # 压缩了行维度，一维数组仅存与当前列匹配的上一行缓存状态
        dp = [0] * (n + 1)

        for i in range(1, m + 1):
            # left_up 记录被当前内层循环覆盖前的左上角数据：即上一行的 dp[j-1]
            left_up = 0
            for j in range(1, n + 1):
                # prev_dp_j 是待会儿马上被更新的局部旧值，即本行的原本正上方数据
                # 更新前将其保存，它将作为下一次迭代（下一列，j+1）的左上角数据
                prev_dp_j = dp[j]

                if text1[i - 1] == text2[j - 1]:
                    # 如果末尾对应匹配，拿左上方保存的历史基线数据直接 + 1
                    dp[j] = left_up + 1
                else:
                    # 没对应上，则在旧的正上方 dp[j] 与本轮左侧新算出的 dp[j-1] 较量中取大者
                    dp[j] = max(dp[j], dp[j - 1])

                # 本轮局部计算结束，将充当旧上方基线的值传给下一轮作为其左上方参数
                left_up = prev_dp_j

        return dp[n]
